		cmp = Integer.compare(planeOf(a, outgoingDirection), planeOf(b, outgoingDirection));
		if (cmp != 0) {
			return cmp;
		}
		cmp = Long.compareUnsigned(sealed.predicates[a], sealed.predicates[b]);
		if (cmp != 0) {
			return cmp;
		}
		cmp = Long.compareUnsigned(neighborOf(a, outgoingDirection), neighborOf(b, outgoingDirection));
		if (cmp != 0) {
			return cmp;
		}
		cmp = Long.compareUnsigned(sealed.contexts[a], sealed.contexts[b]);
		if (cmp != 0) {
			return cmp;
		}
		return Integer.compare(a, b); // event ordinal is the transaction sequence
