	private static final class Directory {
		long[] keys = new long[8];
		byte[] planes = new byte[8];
		long[] predicates = new long[8];
		long[] runRefs = new long[8];
		int size;

		void add(long key, int plane, long predicate, long runRef) {
			if (size == keys.length) {
				keys = Arrays.copyOf(keys, keys.length * 2);
				planes = Arrays.copyOf(planes, planes.length * 2);
				predicates = Arrays.copyOf(predicates, predicates.length * 2);
				runRefs = Arrays.copyOf(runRefs, runRefs.length * 2);
			}
			keys[size] = key;
			planes[size] = (byte) plane;
			predicates[size] = predicate;
			runRefs[size] = runRef;
			size++;
		}

		/** Sorts by unsigned (rawKey, plane, rawPredicate); each direction pass appended in this order already. */
		Directory sortedCopy() {
			Integer[] order = new Integer[size];
			for (int i = 0; i < size; i++) {
				order[i] = i;
			}
			Arrays.sort(order, (a, b) -> {
				int cmp = Long.compareUnsigned(keys[a], keys[b]);
				if (cmp != 0) {
					return cmp;
				}
				cmp = Byte.compare(planes[a], planes[b]);
				if (cmp != 0) {
					return cmp;
				}
				return Long.compareUnsigned(predicates[a], predicates[b]);
			});
			Directory sorted = new Directory();
			sorted.keys = new long[size];
			sorted.planes = new byte[size];
			sorted.predicates = new long[size];
			sorted.runRefs = new long[size];
			sorted.size = size;
			for (int i = 0; i < size; i++) {
				sorted.keys[i] = keys[order[i]];
				sorted.planes[i] = planes[order[i]];
				sorted.predicates[i] = predicates[order[i]];
				sorted.runRefs[i] = runRefs[order[i]];
			}
			return sorted;
		}
	}

